import type { AssessmentFields } from './Assessment'

/**
 * Risk level for a change risk assessment threshold.
 *
 * DB: `risk` (choice). Values: `high`, `moderate`, `low`.
 */
type RiskLevel = 'high' | 'moderate' | 'low'

/**
 * A threshold row in a change risk assessment (`change_risk_asmt_threshold`).
 * Each threshold maps a minimum score to a risk level. The `assessment` foreign
 * key is wired automatically from the parent risk assessment.
 */
type RiskThresholdConfig = Now.Internal.WithID<{
    /** Risk level label. DB: `risk` (choice: high, moderate, low). */
    risk: RiskLevel
    /** Minimum score that triggers this risk level. DB: `score_greater_than` (integer). */
    scoreGreaterThan: number
}>

/**
 * Configuration for a change risk assessment (`change_risk_asmt`), which extends
 * `asmt_metric_type`. Only `name` is mandatory; `table` is always
 * `'change_request'` (not configurable) and `evaluation_method` defaults to
 * `'risk_assessment'` inside the plugin.
 */
export type RiskAssessmentConfig = Now.Internal.WithIdAndMetadata<
    AssessmentFields<'change_request'> & {
        /** Risk thresholds that map score ranges to risk levels (`change_risk_asmt_threshold`). */
        thresholds?: RiskThresholdConfig[]
    }
>

/**
 * Creates a ServiceNow change risk assessment definition (`change_risk_asmt`)
 * together with its thresholds (`change_risk_asmt_threshold`), categories
 * (`asmt_metric_category`), and questions/metrics (`asmt_metric`) as a single
 * nested entity. The plugin defaults `table` to `'change_request'` and
 * `evaluation_method` to `'risk_assessment'`.
 *
 * @param config - The risk assessment configuration object
 *
 * @example
 * ```ts
 * RiskAssessment({
 *     $id: Now.ID['change-risk'],
 *     name: 'Change Risk Assessment',
 *     thresholds: [
 *         { $id: Now.ID['high-risk'], risk: 'high', scoreGreaterThan: 70 },
 *         { $id: Now.ID['moderate-risk'], risk: 'moderate', scoreGreaterThan: 30 },
 *         { $id: Now.ID['low-risk'], risk: 'low', scoreGreaterThan: 0 },
 *     ],
 * })
 * ```
 */
export function RiskAssessment(config: RiskAssessmentConfig) {
    return config
}
